import com.praxicraft.assess.Client; import java.util.*;
public class Main { public static void main(String[] a) throws Exception { Client c=new Client(); Map m=c.assessments().create(Map.of("title","Example screen")); String slug=(String)m.get("slug"); System.out.println(slug); String id=System.getenv("PRAXICRAFT_CASE_ID"); if(id!=null&&!id.isBlank()) c.assessments().attachCases(slug, Map.of("cases", List.of(Map.of("case_id",id,"source","platform")))); } }
